#include "simulation.hpp"
#include <iostream>
#include <stdexcept>
using namespace ofo;
int main(int argc,char**argv){try{Resources r(argv[1]);for(int id:{3,15}){auto c=load_vehicle(r,id,argv[2]);auto tire=load_geometry(r,c.tire);if(tire.triangles<10)throw std::runtime_error("Wheel geometry empty");for(int s=1;s<=5;s++)if(!r.exists("cars/car_"+std::to_string(id)+"/skin"+std::to_string(s)+".dds"))throw std::runtime_error("Skin missing");}auto stages=first_build_stages(r);if(stages.empty())throw std::runtime_error("No launch stages");for(auto&s:stages){auto g=load_geometry(r,stage_geometry(s));auto spawn=load_spawn(r,s);if(g.triangles<60000||!std::isfinite(spawn[13]))throw std::runtime_error("Invalid launch geometry/spawn");if(!r.exists(s+"/lighting/lightmap1_w2.dds"))throw std::runtime_error("Lightmap missing");for(int id:{3,15}){auto c=load_vehicle(r,id,argv[2]);Simulation sim(g,c,spawn);for(int n=0;n<250;n++)sim.step({});float load=0;for(float f:sim.state().wheel_load)load+=f;if(load<c.mass*9.81f*.2f)throw std::runtime_error("No settled wheel contact on launch track: "+s+" car "+std::to_string(id));for(int n=0;n<200;n++){Input in;in.throttle=1;sim.step(in);}if(!std::isfinite(sim.state().speed)||std::abs(sim.state().speed)<1)throw std::runtime_error("Launch drive smoke test failed");}std::cout<<s<<" triangles="<<g.triangles<<'\n';}for(auto&p:{"menu/bg-mainmenu.tga","global/fonts/regular_18.abc","global/fonts/regular_18.dds","global/fonts/italic_24.abc","global/fonts/italic_24.dds","global/overlay/meters_basen.dds","global/overlay/rpm_needle.dds","global/overlay/meters_glass.dds","global/overlay/nitro_light.dds"})if(!r.exists(p))throw std::runtime_error(std::string("UI resource missing: ")+p);std::cout<<"Launch asset contract passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
